(() => {
  'use strict';
  const STORAGE = 'd0174-platform-state-v1';
  const MODULES = {
    overview: { label:'管理總覽', icon:'⌂' },
    people: { label:'人員檔案', icon:'◉' },
    attendance: { label:'團隊出勤', icon:'▦' },
    leavers: { label:'離職管理', icon:'↪' },
    reports: { label:'報表中心', icon:'▥' }
  };
  const today = new Date();
  const defaultMonth = `${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}`;
  const initialState = () => ({ version:1, divisionId:'D0174', members:[], newcomers:[], attendance:[], meetings:[], leavers:[], logs:[], reportUploads:[] });
  let state = loadState();
  let view = { module:'overview', overviewTab:'selector', peopleTab:'directory', attendanceTab:'personal', month:defaultMonth, selectedLeaver:null, search:'' };
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const esc = (v='') => String(v).replace(/[&<>'"]/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[ch]));
  const uid = (prefix) => `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;
  function loadState(){ try { const raw=localStorage.getItem(STORAGE); if(!raw) return initialState(); const parsed=JSON.parse(raw); return {...initialState(),...parsed,divisionId:'D0174'}; } catch { return initialState(); } }
  function save(){ state.divisionId='D0174'; localStorage.setItem(STORAGE,JSON.stringify(state)); }
  function monthLabel(v){ const [y,m]=v.split('-'); return `${y}年${Number(m)}月`; }
  function fmtDate(v){ if(!v) return '—'; return v.replace(/^(\d{4})-(\d{2})-(\d{2})$/,'$1/$2/$3'); }
  function toast(message, kind='ok'){ const root=$('#toast-root'); root.innerHTML=`<div class="toast ${kind}">${esc(message)}</div>`; setTimeout(()=>root.innerHTML='',2600); }
  function download(name, content, mime='text/plain;charset=utf-8'){ const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([content],{type:mime})); a.download=name; a.click(); setTimeout(()=>URL.revokeObjectURL(a.href),500); }
  function csv(rows){ return rows.map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n'); }
  function selectedMonth(){ return view.month || defaultMonth; }
  function statusTag(status){ const map={active:['在職',''],new:['新人','pending'],inactive:['離職','blue'],present:['出席',''],absent:['缺席','pending'],pending:['待確認','pending'],done:['已完成',''],progress:['進行中','pending']}; const [label,cls]=map[status]||[status||'未設定','blue']; return `<span class="tag ${cls}">${label}</span>`; }
  function nav(){ return `<aside class="sidebar"><div class="brand"><div class="brand-mark">卓越<br>SUMMIT</div><div><b>D0174 分區</b><small>運營管理工作台</small></div></div><div class="nav-group">日常工作</div><nav class="nav">${navButton('overview')}</nav><div class="nav-group">團隊管理</div><nav class="nav">${navButton('people')}${navButton('attendance')}${navButton('leavers')}</nav><div class="nav-group">報表與洞察</div><nav class="nav">${navButton('reports')}</nav><div class="sidebar-foot"><b>D0174 內部管理平台</b><br>獨立資料集 · 只保留分區運營模組</div></aside>`; }
  function navButton(id){ const m=MODULES[id]; return `<button class="${view.module===id?'active':''}" data-action="nav" data-module="${id}"><span class="nav-icon">${m.icon}</span>${m.label}</button>`; }
  function topbar(){ return `<header class="topbar"><div class="breadcrumb">卓越 SUMMIT ／ D0174 分區 ／ <b>${MODULES[view.module].label}</b></div><div class="top-actions"><button class="read-only">只讀預覽</button><button aria-label="搜尋" data-action="focus-search">⌕</button><button aria-label="通知">◌</button><button class="avatar">卓</button></div></header>`; }
  function layout(){ $('#app').innerHTML=`${nav()}<main class="main">${topbar()}<div class="content">${renderView()}</div></main>`; bind(); }
  function renderView(){ switch(view.module){ case 'people': return renderPeople(); case 'attendance': return renderAttendance(); case 'leavers': return renderLeavers(); case 'reports': return renderReports(); default: return renderOverview(); } }
  function renderOverview(){ const active=state.members.filter(m=>m.status!=='inactive').length; const monthAtt=state.attendance.filter(a=>a.month===selectedMonth()); const present=monthAtt.filter(a=>a.status==='present').length; const rate=monthAtt.length?Math.round(present/monthAtt.length*100):0; const newCount=state.newcomers.filter(n=>n.startMonth===selectedMonth()).length; const pending=state.newcomers.filter(n=>n.steps?.some(s=>!s.done)).length; const logs=state.logs.slice(-5).reverse(); return `<section class="section active"><div class="hero"><div><div class="eyebrow">D0174 · TEAM DASHBOARD</div><h1>今天需要關注什麼？</h1><p>集中查看 D0174 團隊、人員、出勤與入職流程。</p></div><div class="actions"><select class="select compact" data-field="month"><option value="${selectedMonth()}">${monthLabel(selectedMonth())}</option></select></div></div><div class="cards"><div class="card red"><h3>團隊活躍成員</h3><div class="metric">${active}</div><div class="metric-note">D0174 在職人員 · 初始資料集為空</div><div class="progress"><i style="width:${active?100:0}%"></i></div></div><div class="card"><h3>${monthLabel(selectedMonth())} 出勤完成</h3><div class="metric" style="color:var(--green)">${rate}%</div><div class="metric-note">${present} 人已標記出席</div><div class="progress"><i style="width:${rate}%"></i></div></div><div class="card"><h3>本月新人</h3><div class="metric" style="color:var(--red)">${newCount}</div><div class="metric-note">${pending} 個入職檔案需要跟進</div></div><div class="card"><h3>離職流程</h3><div class="metric" style="color:var(--amber)">${state.leavers.length}</div><div class="metric-note">含通知、交接、權限回收狀態</div></div></div><div class="split"><div class="card"><div class="card-header"><h2>團隊最新動態</h2><span class="muted">只顯示 D0174</span></div>${logs.length?`<div class="activity">${logs.map(log=>`<div class="activity-row"><span class="status-dot ${log.kind==='pending'?'pending':''}"></span><div class="activity-main"><b>${esc(log.title)}</b><span>${esc(log.detail||'')}</span></div><span class="tag ${log.kind==='pending'?'pending':''}">${esc(log.status||'已更新')}</span></div>`).join('')}</div>`:`<div class="empty"><strong>尚未建立運營記錄</strong>建立人員、出勤或入職資料後，最新動態會顯示在這裡。<br><button class="btn primary" data-action="nav" data-module="people">前往人員檔案</button></div>`}</div><div class="card"><div class="card-header"><h2>快速入口</h2><span class="muted">常用</span></div><div class="quick-grid"><button data-action="nav" data-module="people"><b>◉ 人員檔案</b><span>名單、檔案、新人流程</span></button><button data-action="nav" data-module="attendance"><b>▦ 團隊出勤</b><span>月度出勤與會議記錄</span></button><button data-action="nav" data-module="leavers"><b>↪ 離職管理</b><span>交接及權限回收</span></button><button data-action="nav" data-module="reports"><b>▥ 報表中心</b><span>預覽、下載與匯出</span></button></div></div></div></section>`; }
  function renderPeople(){ const tabs=[['directory','團隊名單','通訊錄及分組'],['archive','團隊檔案','全體成員一人一檔'],['newcomers','新人檔案','按月份查看入職批次'],['onboarding','新人入職流程','按步驟辦理與節點']]; return `<section class="section active"><div class="hero"><div><div class="eyebrow">AGENT MASTER · D0174</div><h1>Agent 人員檔案</h1><p>以 D0174 Agent Code 作唯一識別，集中管理團隊名單、檔案與新人流程。</p></div><div class="actions">${view.peopleTab==='directory'?'<button class="btn primary" data-action="open-member">＋ 新增成員</button>':'<button class="btn primary" data-action="open-newcomer">＋ 建立新人檔案</button>'}<button class="btn" data-action="export-members">↓ 導出 Excel</button></div></div><div class="subtabs">${tabs.map(t=>`<button class="subtab ${view.peopleTab===t[0]?'active':''}" data-action="people-tab" data-tab="${t[0]}"><strong>${t[1]}</strong><span>${t[2]}</span></button>`).join('')}</div>${view.peopleTab==='directory'?renderDirectory():view.peopleTab==='archive'?renderArchive():view.peopleTab==='newcomers'?renderNewcomers():renderOnboarding()}</section>`; }
  function renderDirectory(){ const q=view.search.trim().toLowerCase(); const rows=state.members.filter(m=>!q||[m.name,m.code,m.role,m.group].join(' ').toLowerCase().includes(q)); return `<div class="filter-card"><div class="field grow"><label>搜尋姓名、Agent Code 或職級</label><input class="input" data-field="search" value="${esc(view.search)}" placeholder="例如：D0174-0001"></div><div class="field"><label>分組</label><select class="select" data-field="group-filter"><option value="">全部分組</option>${[...new Set(state.members.map(m=>m.group).filter(Boolean))].map(g=>`<option>${esc(g)}</option>`).join('')}</select></div><div class="field"><label>狀態</label><select class="select" data-field="status-filter"><option value="">全部狀態</option><option value="active">在職</option><option value="new">新人</option><option value="inactive">離職</option></select></div></div><div class="card"><div class="card-header"><div><h2>D0174 團隊通訊錄</h2><span class="muted">${rows.length} 筆資料 · 匯出內容只包含 D0174</span></div><div class="actions"><button class="btn small" data-action="import-json">↑ 匯入資料</button><button class="btn small" data-action="clear-search">清除篩選</button></div></div>${rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>序號</th><th>Agent</th><th>職級／角色</th><th>分組</th><th>直接上線</th><th>狀態</th><th>操作</th></tr></thead><tbody>${rows.map((m,i)=>`<tr><td>${i+1}</td><td><b>${esc(m.name)}</b><br><span class="muted">${esc(m.code)}</span></td><td>${esc(m.role||'—')}</td><td>${esc(m.group||'—')}</td><td>${esc(m.manager||'—')}</td><td>${statusTag(m.status)}</td><td><div class="actions"><button class="btn small" data-action="edit-member" data-id="${m.id}">修改</button><button class="btn small danger" data-action="delete-member" data-id="${m.id}">刪除</button></div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><strong>尚未建立團隊名單</strong>新增第一位 D0174 成員後，通訊錄、分組與後續流程會在這裡管理。<br><button class="btn primary" data-action="open-member">＋ 建立成員檔案</button></div>`}</div>`; }
  function renderArchive(){ return `<div class="cards three"><div class="card"><h3>完整個人檔案</h3><div class="metric">${state.members.length}</div><div class="metric-note">每位成員一人一檔</div></div><div class="card"><h3>待補檔案</h3><div class="metric" style="color:var(--amber)">${state.members.filter(m=>!m.archiveReady).length}</div><div class="metric-note">由負責人跟進檔案完整度</div></div><div class="card"><h3>可導出檔案</h3><div class="metric" style="color:var(--green)">${state.members.filter(m=>m.archiveReady).length}</div><div class="metric-note">可下載 D0174 團隊檔案摘要</div></div></div><div class="card"><div class="card-header"><div><div class="eyebrow">TEAM MASTER ARCHIVE</div><h2>團隊檔案 · 一人一檔</h2><span class="muted">完成成員建立後，可在這裡查看檔案完整度與入口。</span></div><button class="btn primary" data-action="export-archive">↓ 導出團隊檔案</button></div>${state.members.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Agent</th><th>角色</th><th>狀態</th><th>檔案完整度</th><th>操作</th></tr></thead><tbody>${state.members.map(m=>`<tr><td><b>${esc(m.name)}</b><br><span class="muted">${esc(m.code)}</span></td><td>${esc(m.role||'—')}</td><td>${statusTag(m.status)}</td><td><div class="meter"><i style="width:${m.archiveReady?100:35}%"></i></div><span class="muted">${m.archiveReady?'已完成':'待補資料'}</span></td><td><button class="btn small" data-action="edit-member" data-id="${m.id}">開啟檔案</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><strong>尚未建立團隊檔案</strong>人員加入 D0174 後會自動產生個人檔案入口。</div>`}</div>`; }
  function renderNewcomers(){ const rows=state.newcomers.filter(n=>n.startMonth===selectedMonth()); return `<div class="filter-card"><div class="field"><label>查看月份</label><select class="select" data-field="month"><option value="${selectedMonth()}">${monthLabel(selectedMonth())}</option>${monthOptions().map(v=>`<option value="${v}">${monthLabel(v)}</option>`).join('')}</select></div><div class="actions"><button class="btn primary" data-action="open-newcomer">＋ 建立新人檔案</button><button class="btn" data-action="export-newcomers">↓ 導出本月新人表</button></div></div><div class="cards"><div class="card red"><h3>本月新人檔案</h3><div class="metric">${rows.length}</div><div class="metric-note">${monthLabel(selectedMonth())} 批次</div></div><div class="card"><h3>入職前辦理中</h3><div class="metric" style="color:var(--amber)">${rows.filter(n=>n.status==='preboarding').length}</div><div class="metric-note">七步流程尚未完成</div></div><div class="card"><h3>已完成正式入職</h3><div class="metric" style="color:var(--green)">${rows.filter(n=>n.status==='active').length}</div><div class="metric-note">已建立團隊檔案</div></div><div class="card"><h3>入職後待完成</h3><div class="metric" style="color:var(--red)">${rows.filter(n=>n.status==='followup').length}</div><div class="metric-note">30／60／90 日節點</div></div><div class="card"><h3>已中止／保留</h3><div class="metric" style="color:var(--muted)">${rows.filter(n=>n.status==='stopped').length}</div><div class="metric-note">保留歷史，不刪除檔案</div></div></div><div class="card"><div class="card-header"><div><div class="eyebrow">NEW AGENT ARCHIVE</div><h2>新人入職進度檔案</h2><span class="muted">按月份查看入職批次；完成入職後可轉入團隊檔案。</span></div><input class="input" data-field="newcomer-search" placeholder="搜尋姓名或 Agent Code" style="max-width:230px"></div>${rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>新人</th><th>入職日期</th><th>負責人</th><th>流程進度</th><th>狀態</th><th>操作</th></tr></thead><tbody>${rows.map(n=>`<tr><td><b>${esc(n.name)}</b><br><span class="muted">${esc(n.code||'尚未分配')}</span></td><td>${fmtDate(n.startDate)}</td><td>${esc(n.owner||'—')}</td><td>${n.steps.filter(s=>s.done).length}/${n.steps.length}</td><td>${statusTag(n.status==='active'?'active':n.status==='followup'?'progress':n.status==='stopped'?'inactive':'pending')}</td><td><button class="btn small" data-action="open-onboarding" data-id="${n.id}">查看流程</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><strong>尚未建立${monthLabel(selectedMonth())}新人檔案</strong>點擊「建立新人檔案」開始辦理入職批次，之後會在這裡顯示月份、狀態與流程進度。</div>`}</div>`; }
  function renderOnboarding(){ const rows=state.newcomers; const requirements=[['01','身份要求','香港永久居民、香港居民、有效簽證及可核對身份文件'],['02','學歷要求','符合相關職位最低學歷或專業資格'],['03','考試要求','完成保險中介人資格考試或指定入職測試']]; const categories=['香港永久居民','DI／單程證','受養人','優才／高才／資本投資／有效IANG','學生簽證','海外國籍','已失效IANG']; const identityDocs=['香港身份證（正本）','首次入境的小白條（正本）','香港入境簽證（A4 紙）','港澳通行證（有效正本）','內地身份證（正本）','白底近期證件相片','最高學歷證明文件','學位證明（與畢業證書一致）']; const commonDocs=['香港身份證（不接受「行街紙」）','最高學歷證明文件','近三個月內地址證明','銀行存摺本／銀行月結單','彩色正面半身證件相片','於入職申請表填寫的資料副本']; const flow=[['1','資格、報考及 IIQE','確認身份與學歷要求，完成報考、卷一／卷三／卷五及考試結果記錄。'],['2','入職申請及文件','填寫新人檔案、上傳專業頭像、收集身份、地址、學歷及銀行文件。'],['3','牌照／保險局','提交牌照申請、追蹤 Pending／Approved，補齊行政缺件。'],['4','Agent Code','取得 Agent Code 後補回檔案，建立正式團隊身份與上線關係。'],['5','預備首合約','確認財務計劃、團隊安排、首合約文件與入職前行政事項。'],['6','正式入職及首合約','保存入職完成日期，系統生成首合約日期並完成正式入職確認。'],['7','出 Code 後課程跟進','依 D0、D5、30／60／90 日及後續課程節點追蹤新人。']]; const follow=[['D0','第一天入職','團隊介紹、行政帳戶、設備及第一週安排。'],['D5','第五天檢視','確認文件、課程、工作適應與缺件補交。'],['30／60日','試用期節點','檢視工作進度、出勤、支援與團隊回饋。'],['90日','入職結案','完成試用期總結、首合約及後續發展安排。']]; return `<div class="card red" style="margin-bottom:16px"><div class="eyebrow" style="color:#ffe1e3">2026 NEW JOINER PLAYBOOK</div><div style="display:flex;justify-content:space-between;gap:20px;align-items:end"><div><h2 style="font-size:24px;margin:8px 0;color:#fff">正式入職前七步＋出 Code 後課程跟進</h2><p style="color:#ffe1e3;margin:0">保留 D0133 的新人工作手冊、文件要求、流程節點及入職後跟進。</p></div><div style="font-size:30px;font-weight:800">${rows.filter(n=>n.steps?.some(s=>!s.done)).length}<div style="font-size:11px;font-weight:500">待跟進新人</div></div></div></div><div class="card" style="margin-bottom:16px"><div class="card-header"><div><div class="eyebrow">START HERE</div><h2>新人從這裡開始</h2><span class="muted">先確認資格，再聯絡招募經理建立資料；收到連結或電郵後進入相應平台操作。</span></div><button class="btn primary" data-action="open-newcomer">＋ 建立新人檔案</button></div><div class="form-grid three"><div class="step-item"><div><b>新人自己做</b><span>準備材料、註冊、選考試場次、核對並簽署入職申請。</span></div></div><div class="step-item"><div><b>招募經理做</b><span>建立新人、發出考試連結、代報／確認考試，建立跟進計劃。</span></div></div><div class="step-item"><div><b>行政／公司做</b><span>核對文件、建立保險局帳戶、提交牌照申請，跟進批核及開通。</span></div></div></div><div style="margin-top:10px;background:#27313d;color:#fff;border-radius:10px;padding:12px 14px;font-size:12px"><b>第一個行動</b>　把英文姓名（與證件一致）及香港手提電話交給招募經理，等待下一步連結。</div></div><div class="card" style="margin-bottom:16px"><div class="card-header"><div><div class="eyebrow">ELIGIBILITY CHECK</div><h2>新人資格與文件要求</h2></div><span class="tag blue">${categories.length} 個身份類別</span></div><div class="form-grid three">${requirements.map(r=>`<div class="step-item"><strong style="color:var(--red)">${r[0]}</strong><div><b>${r[1]}</b><span>${r[2]}</span></div></div>`).join('')}</div><div class="actions" style="margin-top:15px;flex-wrap:wrap">${categories.map((c,i)=>`<span class="tag ${i===3?'':'blue'}">${c}</span>`).join('')}</div></div><div class="form-grid"><div class="card"><div class="card-header"><h2>身份及資格證明專屬文件</h2><span class="muted">${identityDocs.length} 項</span></div><div class="activity">${identityDocs.map((d,i)=>`<div class="activity-row"><span class="status-dot pending"></span><div class="activity-main"><b>${String(i+1).padStart(2,'0')}　${d}</b><span>建立新人檔案後逐項上傳與核對</span></div></div>`).join('')}</div></div><div class="card"><div class="card-header"><h2>所有身份類別共同準備</h2><span class="muted">${commonDocs.length} 項</span></div><div class="activity">${commonDocs.map((d,i)=>`<div class="activity-row"><span class="status-dot pending"></span><div class="activity-main"><b>${String(i+1).padStart(2,'0')}　${d}</b><span>行政核對後更新文件狀態</span></div></div>`).join('')}</div></div></div><div class="card" style="margin-top:16px"><div class="card-header"><div><div class="eyebrow">SEVEN STEP FLOW</div><h2>新人入職流程手冊</h2><span class="muted">按 D0133 的長流程結構逐步辦理，每一階段都可在新人檔案中追蹤。</span></div></div><div class="form-grid">${flow.map((f,i)=>`<div class="card" style="padding:0;border-color:#efd1d3"><div style="background:#2b3440;color:#fff;padding:12px 14px;border-radius:13px 13px 0 0"><b>${f[0]}　${f[1]}</b></div><div style="padding:14px"><p class="muted" style="margin:0 0 12px">${f[2]}</p><div class="step-list"><div class="step-item"><span class="tag pending">待辦</span><div><b>文件／節點狀態</b><span>完成後於新人檔案勾選並補充備註。</span></div></div><div class="step-item"><span class="tag blue">跟進</span><div><b>行政下一步</b><span>指定負責人、日期及缺少材料。</span></div></div></div></div></div>`).join('')}</div></div><div class="card" style="margin-top:16px"><div class="card-header"><div><div class="eyebrow">AFTER CODE FOLLOW-UP</div><h2>出 Code 後課程與入職節點</h2></div><span class="muted">D0／D5／30／60／90 日</span></div><div class="form-grid four">${follow.map(f=>`<div class="step-item"><strong style="color:var(--red)">${f[0]}</strong><div><b>${f[1]}</b><span>${f[2]}</span></div></div>`).join('')}</div></div><div class="card" style="margin-top:16px"><div class="toolbar"><div><div class="eyebrow">PROCESS TRACKER</div><h2 style="margin:7px 0 5px;font-size:19px">D0174 新人流程清單</h2><span class="muted">${rows.length} 個流程 · ${rows.filter(n=>n.steps?.every(s=>s.done)).length} 個已完成</span></div><button class="btn primary" data-action="open-newcomer">＋ 建立新人檔案</button></div>${rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>新人</th><th>入職批次</th><th>流程節點</th><th>進度</th><th>狀態</th><th>操作</th></tr></thead><tbody>${rows.map(n=>{const done=n.steps.filter(s=>s.done).length;return `<tr><td><b>${esc(n.name)}</b><br><span class="muted">${esc(n.code||'尚未分配')}</span></td><td>${monthLabel(n.startMonth)}</td><td>${n.steps.length} 個節點</td><td><div class="meter"><i style="width:${Math.round(done/n.steps.length*100)}%"></i></div><span class="muted">${done}/${n.steps.length}</span></td><td>${statusTag(done===n.steps.length?'active':done?'progress':'pending')}</td><td><button class="btn small" data-action="open-onboarding" data-id="${n.id}">按步驟辦理</button></td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty"><strong>尚未建立入職流程</strong>上方資格、文件與七個流程階段已準備好；建立新人檔案後即可逐項勾選狀態。</div>`}</div>`; }
  function monthOptions(){ const out=[]; for(let i=-2;i<=4;i++){const d=new Date(today.getFullYear(),today.getMonth()+i,1);out.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`)} return out; }
  function renderAttendance(){ const month=selectedMonth(); const records=state.attendance.filter(a=>a.month===month); const present=records.filter(a=>a.status==='present').length; return `<section class="section active"><div class="hero"><div><div class="eyebrow">ATTENDANCE · D0174</div><h1>團隊出勤總覽</h1><p>選擇月份查看人員出勤、分析評估、會議記錄與出勤明細。</p></div><div class="actions"><select class="select compact" data-field="month"><option value="${month}">${monthLabel(month)}</option>${monthOptions().map(v=>`<option value="${v}">${monthLabel(v)}</option>`).join('')}</select><button class="btn" data-action="export-attendance">↓ 導出月份出勤表</button></div></div><div class="cards"><div class="card"><h3>${monthLabel(month)} 需計出勤 Agent</h3><div class="metric">${state.members.filter(m=>m.status!=='inactive').length}</div><div class="metric-note">目前 D0174 在職名單</div></div><div class="card"><h3>已舉行會議全勤</h3><div class="metric" style="color:var(--green)">${records.filter(a=>a.status==='present').length}</div><div class="metric-note">出席人次</div></div><div class="card"><h3>部分出席</h3><div class="metric" style="color:var(--amber)">${records.filter(a=>a.status==='partial').length}</div><div class="metric-note">需要確認的記錄</div></div><div class="card"><h3>已舉行會議未出席</h3><div class="metric" style="color:var(--red)">${records.filter(a=>a.status==='absent').length}</div><div class="metric-note">可補簽或申請請假</div></div></div><div class="subtabs three">${[['personal','人員出勤','逐人查看月度及年度出勤率'],['analysis','分析評估','對照出勤與業績表現'],['meetings','會議記錄','請假、簽到、補簽與出席']].map(t=>`<button class="subtab ${view.attendanceTab===t[0]?'active':''}" data-action="attendance-tab" data-tab="${t[0]}"><strong>${t[1]}</strong><span>${t[2]}</span></button>`).join('')}</div>${view.attendanceTab==='personal'?renderAttendancePersonal(records,month):view.attendanceTab==='analysis'?renderAttendanceAnalysis(records,month):renderMeetings(month)}</section>`; }
  function renderAttendancePersonal(records,month){ const rows=records; return `<div class="card"><div class="card-header"><div><div class="eyebrow">ATTENDANCE LIST</div><h2>${monthLabel(month)} 人員出勤明細</h2></div><div class="actions"><input class="input" data-field="attendance-search" placeholder="搜尋姓名或 Agent Code" style="max-width:220px"><button class="btn primary" data-action="open-attendance">＋ 新增出勤</button></div></div>${rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Agent</th><th>行政區</th><th>D0174 分區</th><th>年度累計出勤率</th><th>本月狀態</th><th>本月業績</th><th>操作</th></tr></thead><tbody>${rows.map(a=>{const m=state.members.find(x=>x.id===a.memberId)||{};return `<tr><td><b>${esc(m.name||a.name)}</b><br><span class="muted">${esc(m.code||a.code||'')}</span></td><td>${esc(a.region||'—')}</td><td>${statusTag(a.status)}</td><td>${Number(a.annualRate||0)}%</td><td>${statusTag(a.status)}</td><td>HK$ ${Number(a.performance||0).toLocaleString()}</td><td><button class="btn small" data-action="edit-attendance" data-id="${a.id}">修改</button></td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty"><strong>尚未建立${monthLabel(month)}出勤記錄</strong>先建立團隊成員，再為指定月份新增出勤狀態。</div>`}</div>`; }
  function renderAttendanceAnalysis(records,month){ const total=records.length, present=records.filter(a=>a.status==='present').length, perf=records.reduce((s,a)=>s+Number(a.performance||0),0); return `<div class="cards three"><div class="card"><h3>出勤 Agent 中有批單</h3><div class="metric">${records.filter(a=>Number(a.performance||0)>0).length}/${total}</div><div class="metric-note">用來觀察出勤與業績的關係</div></div><div class="card"><h3>出勤人員本月開單比例</h3><div class="metric" style="color:var(--green)">${total?Math.round(present/total*100):0}%</div><div class="metric-note">只作管理觀察，不作個人決定</div></div><div class="card"><h3>${monthLabel(month)} 業績總額</h3><div class="metric" style="color:var(--red)">HK$ ${perf.toLocaleString()}</div><div class="metric-note">初始資料集為空，可逐月累積</div></div></div><div class="card"><div class="card-header"><div><div class="eyebrow">MANAGEMENT REVIEW</div><h2>考勤與業績對應評估</h2></div><button class="btn small" data-action="export-analysis">↓ 導出目前分析底表</button></div><div class="form-grid"><div><b style="font-size:13px">出勤參閱度</b><p class="muted">比較全勤、偶爾出席及缺席群組，持續觀察每月變化。</p></div><div><b style="font-size:13px">出勤與業績對應</b><p class="muted">以批單數、業績金額和出勤狀態作並列參考。</p></div><div><b style="font-size:13px">行政跟進建議</b><p class="muted">優先聯絡連續缺席或出勤記錄待確認的人員。</p></div><div><b style="font-size:13px">使用界線</b><p class="muted">出勤是日常管理資料，需配合正式制度與團隊溝通。</p></div></div></div>`; }
  function renderMeetings(month){ const meetings=state.meetings.filter(m=>m.month===month); const latest=meetings[0]; const checkins=latest?.attendees?.length||0; const leaves=latest?.leaves?.length||0; const pending=latest?.pending||0; return `<div class="card"><div class="card-header"><div><div class="eyebrow">MONTHLY MEETING</div><h2>業務交流會</h2><span class="muted">掃碼登記，名單與 D0174 團隊出勤同步。</span></div><button class="btn primary" data-action="open-meeting">＋ 新增／設定本月會議</button></div><div class="form-grid three"><div class="field"><label>會議月份</label><input class="input" type="month" data-field="meeting-month" value="${month}"></div><div class="field"><label>行政總區會議日期</label><input class="input" type="date" value="${latest?.regionDate||''}" disabled></div><div class="field"><label>D0174 分區會議日期</label><input class="input" type="date" value="${latest?.divisionDate||latest?.date||''}" disabled></div></div><div class="info-banner" style="margin-top:14px"><b>會議日期設定</b><span class="muted">　行政總區 ${latest?.regionDate||'未設定'}　／　D0174 ${latest?.divisionDate||latest?.date||'未設定'}</span><button class="btn small" data-action="open-meeting" data-id="${latest?.id||''}">展開設定</button></div><div class="cards four" style="margin-top:16px"><div class="card"><h3>卓越行政總區簽到</h3><div class="metric">${latest?.regionAttendees?.length||0}</div><div class="metric-note">人</div></div><div class="card"><h3>D0174 分區簽到</h3><div class="metric" style="color:var(--green)">${checkins}</div><div class="metric-note">人</div></div><div class="card"><h3>D0174 請假</h3><div class="metric" style="color:var(--amber)">${leaves}</div><div class="metric-note">人</div></div><div class="card"><h3>待核對</h3><div class="metric" style="color:var(--red)">${pending}</div><div class="metric-note">筆</div></div></div><div class="actions" style="margin-top:14px"><button class="btn small" data-action="open-meeting" data-id="${latest?.id||''}">＋ 補登簽到</button><button class="btn small" data-action="export-meetings">導出 Excel ↓</button><span class="tag blue">會議簽到 · D0174</span><span class="tag">D0174 請假</span></div></div><div class="card" style="margin-top:16px"><div class="card-header"><div><div class="eyebrow">MEETING RECORDS</div><h2>會議名單 ${latest?`· ${checkins+leaves} 筆`:''}</h2><span class="muted">按會議月份讀取簽到、請假及補登資料。</span></div><div class="actions"><input class="input" data-field="meeting-search" placeholder="搜尋會議名單" style="max-width:220px"><button class="btn small" data-action="export-meetings">導出 Excel ↓</button></div></div>${meetings.length?`<div class="activity">${meetings.map(m=>`<div class="list-row"><div class="list-main"><b>${esc(m.title||'業務交流會')}</b><span>${fmtDate(m.date||m.divisionDate)} · D0174 簽到 ${m.attendees?.length||0} 人 · 請假 ${m.leaves?.length||0} 人</span></div><span class="tag ${m.pending?'pending':''}">${m.pending||0} 待核對</span><button class="btn small" data-action="open-meeting" data-id="${m.id}">管理</button></div>`).join('')}</div>`:`<div class="empty"><strong>尚未建立${monthLabel(month)}業務交流會</strong>建立月份和會議日期後，可生成簽到／請假入口、補登記錄和出勤明細。</div>`}</div>`; }
  function renderLeavers(){ const month=selectedMonth(); const rows=state.leavers.filter(l=>!month||l.month===month); return `<section class="section active"><div class="hero"><div><div class="eyebrow">OFFBOARDING · D0174</div><h1>離職管理</h1><p>先通知，再移群；同步完成交接、設備、文件與權限回收。</p></div><div class="actions"><select class="select compact" data-field="month"><option value="${month}">${monthLabel(month)}</option>${monthOptions().map(v=>`<option value="${v}">${monthLabel(v)}</option>`).join('')}</select><button class="btn" data-action="export-leavers">↓ 導出所選月份</button><button class="btn primary" data-action="open-leaver">＋ 新增離職人員</button></div></div><div class="info-banner"><h3>處理原則</h3><p>避免在未說明的情況下直接移除關係，保留尊重、有溫度的離職體驗；流程完成後才回收帳號和權限。</p></div><div class="card"><div class="card-header"><div><div class="eyebrow">DEPARTED AGENTS</div><h2>${monthLabel(month)} 離職人員</h2><span class="muted">${rows.length} 筆流程 · 可查看歷史記錄</span></div></div>${rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Agent</th><th>離職時職級</th><th>上線經理</th><th>離職日期</th><th>原因／備註</th><th>完成度</th><th>操作</th></tr></thead><tbody>${rows.map(l=>{const done=l.steps.filter(s=>s.done).length;return `<tr><td><b>${esc(l.name)}</b><br><span class="muted">${esc(l.code||'')}</span></td><td>${esc(l.role||'—')}</td><td>${esc(l.manager||'—')}</td><td>${fmtDate(l.endDate)}</td><td>${esc(l.reason||'—')}</td><td><div class="meter"><i style="width:${done/l.steps.length*100}%"></i></div><span class="muted">${done}/${l.steps.length}</span></td><td><button class="btn small" data-action="open-leaver" data-id="${l.id}">處理</button></td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty"><strong>尚未建立離職流程</strong>建立離職申請後，通知期、交接和權限回收會在這裡追蹤。</div>`}</div>${view.selectedLeaver?renderLeaverDetail():''}</section>`; }
  function renderLeaverDetail(){ const l=state.leavers.find(x=>x.id===view.selectedLeaver); if(!l) return ''; const done=l.steps.filter(s=>s.done).length; return `<div class="card" style="margin-top:16px"><div class="card-header"><div><div class="eyebrow">OFFBOARDING FOLLOW-UP</div><h2>${esc(l.name)} · 離職處理</h2><span class="muted">合約終止日：${fmtDate(l.endDate)} · 負責人：${esc(l.owner||'未指定')}</span></div><button class="btn primary" data-action="save-leaver" data-id="${l.id}">保存離職處理進度</button></div><div class="cards three"><div class="card"><h3>核心處理進度</h3><div class="metric">${done}/${l.steps.length}</div><div class="progress"><i style="width:${done/l.steps.length*100}%"></i></div></div><div class="card"><h3>最後工作日</h3><div class="metric" style="font-size:24px">${fmtDate(l.endDate)}</div><div class="metric-note">通知期與移群安排</div></div><div class="card"><h3>權限狀態</h3><div class="metric" style="font-size:24px;color:${l.steps[3]?.done?'var(--green)':'var(--amber)'}">${l.steps[3]?.done?'已回收':'待回收'}</div><div class="metric-note">完成後才可結案</div></div></div><div class="step-list">${l.steps.map((s,i)=>`<label class="step-item"><input type="checkbox" data-leaver-step="${l.id}" data-step="${i}" ${s.done?'checked':''}><div><b>${i+1}. ${esc(s.title)}</b><span>${esc(s.detail)}</span></div></label>`).join('')}</div><div class="form-grid" style="margin-top:14px"><div class="field full"><label>交接備註</label><textarea class="textarea" data-leaver-note="${l.id}" rows="3" placeholder="記錄保單、客戶、文件、設備或團隊通知安排">${esc(l.note||'')}</textarea></div></div></div>`; }
  function renderReports(){ const month=selectedMonth(); const uploads=state.reportUploads||[]; const functions=[['monthly','月度運營摘要'],['attendance','出勤分析'],['newcomers','新人入職進度'],['leavers','離職與交接']]; return `<section class="section active"><div class="hero"><div><div class="eyebrow">REPORT CENTER · D0174</div><h1>報表中心</h1><p>只保留 D0174 需要的報表上傳入口；D0133 的既有表格與資料已清除。</p></div><div class="actions"><select class="select compact" data-field="month"><option value="${month}">${monthLabel(month)}</option>${monthOptions().map(v=>`<option value="${v}">${monthLabel(v)}</option>`).join('')} </select></div></div><div class="info-banner"><h3>報表資料入口</h3><p>請選擇保留的功能並上傳對應 CSV／Excel／PDF。上傳記錄只會保存檔名、功能、月份與時間，不會讀取或連接 D0133 的資料。</p></div><div class="card"><div class="card-header"><div><div class="eyebrow">UPLOAD CENTER</div><h2>上傳 D0174 報表</h2><span class="muted">資料隔離：divisionId = D0174</span></div><span class="tag blue">空白資料集</span></div><div class="form-grid"><div class="field"><label>保留功能</label><select class="select" data-field="upload-function">${functions.map(f=>`<option value="${f[0]}">${f[1]}</option>`).join('')}</select></div><div class="field"><label>報表月份</label><select class="select" data-field="upload-month"><option value="${month}">${monthLabel(month)}</option>${monthOptions().map(v=>`<option value="${v}">${monthLabel(v)}</option>`).join('')}</select></div><div class="field full"><label>選擇檔案</label><input class="input" type="file" id="report-file" accept=".csv,.xlsx,.xls,.pdf"></div></div><div class="actions" style="margin-top:16px"><button class="btn primary" data-action="upload-report">↑ 上傳至 D0174</button><span class="muted">支援 CSV、Excel、PDF；單次一個檔案</span></div></div><div class="card" style="margin-top:16px"><div class="card-header"><div><h2>已上傳記錄</h2><span class="muted">${uploads.length} 筆 · 只顯示 D0174 上傳入口產生的記錄</span></div><button class="btn small danger" data-action="clear-report-uploads" ${uploads.length?'':'disabled'}>清除記錄</button></div>${uploads.length?`<div class="activity">${uploads.slice().reverse().map(u=>`<div class="list-row"><div class="list-main"><b>${esc(u.name)}</b><span>${esc(functions.find(f=>f[0]===u.function)?.[1]||u.function)} · ${monthLabel(u.month)} · ${esc(u.uploadedAt)}</span></div><button class="btn small danger" data-action="remove-report-upload" data-id="${u.id}">刪除</button></div>`).join('')}</div>`:`<div class="empty"><strong>尚未上傳 D0174 報表</strong>這裡沒有 D0133 的表格或既有資料；請從上方入口加入保留功能的檔案。</div>`}</div></section>`; }
  function bind(){ $$('#app [data-action]').forEach(el=>el.addEventListener('click',handleAction)); $$('#app [data-field]').forEach(el=>{ const event=el.tagName==='INPUT'?'input':'change'; el.addEventListener(event,handleField); }); $$('#app [data-leaver-step]').forEach(el=>el.addEventListener('change',()=>{const l=state.leavers.find(x=>x.id===el.dataset.leaverStep);if(l)l.steps[Number(el.dataset.step)].done=el.checked; render();})); $$('#app [data-leaver-note]').forEach(el=>el.addEventListener('input',()=>{const l=state.leavers.find(x=>x.id===el.dataset.leaverNote);if(l)l.note=el.value;})); }
  function render(){ layout(); }
  function handleField(e){ const el=e.currentTarget; const f=el.dataset.field; if(f==='month'){view.month=el.value; render();} else if(f==='search'){view.search=el.value; render(); const input=$('[data-field="search"]'); if(input){input.focus(); input.setSelectionRange(view.search.length,view.search.length)}} else if(f==='attendance-search'){ view.attendanceSearch=el.value; } }
  function handleAction(e){ const el=e.currentTarget; const a=el.dataset.action; if(a==='nav'){view.module=el.dataset.module;view.selectedLeaver=null;render();} else if(a==='overview-tab'){view.overviewTab=el.dataset.tab;render();} else if(a==='people-tab'){view.peopleTab=el.dataset.tab;render();} else if(a==='attendance-tab'){view.attendanceTab=el.dataset.tab;render();} else if(a==='focus-search'){view.module='people';view.peopleTab='directory';render();setTimeout(()=>{$('[data-field="search"]')?.focus()},0);} else if(a==='clear-search'){view.search='';render();} else if(a==='open-member'){openMember();} else if(a==='edit-member'){openMember(el.dataset.id);} else if(a==='delete-member'){deleteMember(el.dataset.id);} else if(a==='export-members'){exportMembers();} else if(a==='export-archive'){exportArchive();} else if(a==='import-json'){importJson();} else if(a==='open-newcomer'){openNewcomer();} else if(a==='export-newcomers'){exportNewcomers();} else if(a==='open-onboarding'){view.peopleTab='onboarding';openOnboarding(el.dataset.id);} else if(a==='open-attendance'){openAttendance();} else if(a==='edit-attendance'){openAttendance(el.dataset.id);} else if(a==='export-attendance'){exportAttendance();} else if(a==='export-analysis'){exportAnalysis();} else if(a==='open-meeting'){openMeeting(el.dataset.id);} else if(a==='meeting-action'){toast(`${el.dataset.kind==='leave'?'會議請假':el.dataset.kind==='signin'?'會議簽到':'出勤明細'} 已準備，請先建立會議記錄。`,'warn');} else if(a==='export-meetings'){exportMeetings();} else if(a==='open-leaver'){view.selectedLeaver=el.dataset.id||null; if(!el.dataset.id){openLeaver();} else render();} else if(a==='save-leaver'){save();toast('離職處理進度已保存');render();} else if(a==='export-leavers'){exportLeavers();} else if(a==='upload-report'){uploadReport();} else if(a==='remove-report-upload'){state.reportUploads=(state.reportUploads||[]).filter(x=>x.id!==el.dataset.id);save();toast('上傳記錄已刪除','warn');render();} else if(a==='clear-report-uploads'){if(confirm('確定清除所有 D0174 上傳記錄？')){state.reportUploads=[];save();toast('上傳記錄已清除','warn');render();}} else if(a==='preview-report'){previewReport(el.dataset.type);} else if(a==='download-report'){downloadReport(el.dataset.type);} else if(a==='export-all'){download('d0174-data-backup.json',JSON.stringify(state,null,2),'application/json');toast('D0174 JSON 備份已下載');} }
  function modal(title, body, onSubmit, submitLabel='保存'){ const root=$('#modal-root'); root.innerHTML=`<div class="modal-backdrop" data-close-modal><div class="modal" role="dialog" aria-modal="true"><div class="modal-header"><h2>${title}</h2><button class="modal-close" data-close-modal>×</button></div><form id="modal-form"><div class="modal-body">${body}</div><div class="modal-footer"><button type="button" class="btn" data-close-modal>取消</button><button class="btn primary" type="submit">${submitLabel}</button></div></form></div></div>`; root.querySelectorAll('[data-close-modal]').forEach(x=>x.addEventListener('click',e=>{if(e.target===x||x.dataset.closeModal!==undefined)root.innerHTML='';})); $('#modal-form').addEventListener('submit',e=>{e.preventDefault();onSubmit(new FormData(e.currentTarget));root.innerHTML='';}); }
  function openMember(id){ const m=state.members.find(x=>x.id===id)||{name:'',code:'',role:'',group:'',manager:'',status:'active',archiveReady:false}; modal(id?'修改成員檔案':'建立成員檔案',`<div class="form-grid"><div class="field"><label>姓名 *</label><input class="input" name="name" required value="${esc(m.name)}"></div><div class="field"><label>Agent Code *</label><input class="input" name="code" required value="${esc(m.code)}" placeholder="D0174-0001"></div><div class="field"><label>職級／角色</label><input class="input" name="role" value="${esc(m.role)}" placeholder="例如：運營助理"></div><div class="field"><label>分組</label><input class="input" name="group" value="${esc(m.group)}" placeholder="例如：A 組"></div><div class="field"><label>直接上線</label><input class="input" name="manager" value="${esc(m.manager)}"></div><div class="field"><label>狀態</label><select class="select" name="status"><option value="active" ${m.status==='active'?'selected':''}>在職</option><option value="new" ${m.status==='new'?'selected':''}>新人</option><option value="inactive" ${m.status==='inactive'?'selected':''}>離職</option></select></div><label class="field full" style="display:flex;gap:8px;align-items:center"><input type="checkbox" name="archiveReady" ${m.archiveReady?'checked':''}> 檔案基本資料已完成</label></div>`,fd=>{ const data=Object.fromEntries(fd.entries()); const next={...m,id:m.id||uid('mem'),name:data.name.trim(),code:data.code.trim(),role:data.role.trim(),group:data.group.trim(),manager:data.manager.trim(),status:data.status,archiveReady:fd.has('archiveReady')}; if(m.id){Object.assign(state.members.find(x=>x.id===m.id),next);log('人員檔案已更新',next.name,'已更新');} else {state.members.push(next);log('新增 D0174 成員',next.name,'已建立');} save();toast(id?'成員檔案已更新':'D0174 成員已建立');render();}); }
  function deleteMember(id){ const m=state.members.find(x=>x.id===id); if(!m)return; if(!confirm(`確定刪除 ${m.name} 的 D0174 成員檔案？`))return; state.members=state.members.filter(x=>x.id!==id); state.attendance=state.attendance.filter(x=>x.memberId!==id);save();toast('成員檔案已刪除','warn');render(); }
  function openNewcomer(id){ const m=state.newcomers.find(x=>x.id===id)||{name:'',englishName:'',gender:'',code:'',startMonth:selectedMonth(),startDate:'',codeDate:'',completionDate:'',owner:'',status:'preboarding',role:'FC',manager:'',financialPlan:'無',education:'',school:'',currentStep:'第1步｜資格、報考及IIQE',missingMaterials:'',nextAction:'',licenseStatus:'Pending（申請中）',iiqe:[],avatarName:''}; const stepOptions=['第1步｜資格、報考及IIQE','第2步｜入職申請及文件','第3步｜牌照／保險局','第4步｜Agent Code','第5步｜預備首合約','第6步｜正式入職及首合約','第7步｜出 Code 後課程跟進']; const body=`<p class="muted">填寫下方欄便完成新人檔案；尚未取得 Agent Code 也可以先儲存。</p><div class="eyebrow" style="margin:15px 0 10px">基本身份及入職時間</div><div class="form-grid"><div class="field full"><label>上傳專業頭像</label><input class="input" type="file" name="avatar" accept="image/*"><span class="muted">${esc(m.avatarName||'尚未取得 Agent Code 也可以先檔')}</span></div><div class="field"><label>中文姓名 *</label><input class="input" name="name" required value="${esc(m.name)}" placeholder="例如：陳大文"></div><div class="field"><label>英文姓名</label><input class="input" name="englishName" value="${esc(m.englishName)}" placeholder="例如：Chan Tai Man"></div><div class="field"><label>性別</label><div class="actions"><label class="btn small"><input type="radio" name="gender" value="男" ${m.gender==='男'?'checked':''}> 男</label><label class="btn small"><input type="radio" name="gender" value="女" ${m.gender==='女'?'checked':''}> 女</label></div></div><div class="field"><label>入職流程開始日期 *</label><input class="input" type="date" name="startDate" value="${esc(m.startDate)}" required></div><div class="field"><label>Agent Code（取得後再填）</label><input class="input" name="code" value="${esc(m.code)}" placeholder="尚未取得可留空"></div><div class="field"><label>Agent Code 取得日期</label><input class="input" type="date" name="codeDate" value="${esc(m.codeDate)}"></div><div class="field"><label>入職完成日期</label><input class="input" type="date" name="completionDate" value="${esc(m.completionDate)}"></div><div class="field"><label>目前入職狀態</label><select class="select" name="status"><option value="preboarding" ${m.status==='preboarding'?'selected':''}>入職辦理中</option><option value="followup" ${m.status==='followup'?'selected':''}>入職後待完成</option><option value="active" ${m.status==='active'?'selected':''}>已完成正式入職</option><option value="stopped" ${m.status==='stopped'?'selected':''}>已中止／保留</option></select></div></div><div class="eyebrow" style="margin:20px 0 10px">團隊架構及財務計劃</div><div class="form-grid"><div class="field"><label>初始職級</label><select class="select" name="role"><option ${m.role==='FC'?'selected':''}>FC（理財顧問）</option><option ${m.role==='行政支援'?'selected':''}>行政支援</option><option ${m.role==='運營助理'?'selected':''}>運營助理</option></select></div><div class="field"><label>直接上線（輸入姓氏搜尋）</label><input class="input" name="manager" value="${esc(m.manager)}" placeholder="例如輸入：李"></div><div class="field"><label>財務計劃</label><select class="select" name="financialPlan"><option ${m.financialPlan==='無'?'selected':''}>無</option><option ${m.financialPlan==='有'?'selected':''}>有</option><option ${m.financialPlan==='待確認'?'selected':''}>待確認</option></select></div><div class="field full"><label>最高學歷</label><div class="actions" style="flex-wrap:wrap">${['博士（PhD）','碩士（Master）','本科（Bachelor）','大專／副學士（Diploma）','高中或以下（High School）'].map(v=>`<label class="btn small"><input type="radio" name="education" value="${v}" ${m.education===v?'checked':''}> ${v}</label>`).join('')}</div></div><div class="field full"><label>具體院校名稱</label><input class="input" name="school" value="${esc(m.school)}" placeholder="例如：香港大學"></div></div><div class="eyebrow" style="margin:20px 0 10px">入職流程進度</div><div class="form-grid"><div class="field"><label>目前進行步驟</label><select class="select" name="currentStep">${stepOptions.map(v=>`<option ${m.currentStep===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>牌照狀態</label><select class="select" name="licenseStatus"><option ${m.licenseStatus==='Pending（申請中）'?'selected':''}>Pending（申請中）</option><option ${m.licenseStatus==='Approved（已批核）'?'selected':''}>Approved（已批核）</option><option ${m.licenseStatus==='Not started（未開始）'?'selected':''}>Not started（未開始）</option></select></div><div class="field full"><label>目前缺少材料</label><textarea class="textarea" name="missingMaterials" rows="3" placeholder="例如：香港住址證明、學歷證書">${esc(m.missingMaterials)}</textarea></div><div class="field full"><label>行政下一步跟進事項</label><textarea class="textarea" name="nextAction" rows="3" placeholder="例如：提醒新人完成一站通補件">${esc(m.nextAction)}</textarea></div><div class="field full"><label>已通過的 IIQE 考試</label><div class="actions"><label class="btn small"><input type="checkbox" name="iiqe" value="卷一" ${m.iiqe?.includes('卷一')?'checked':''}> 卷一</label><label class="btn small"><input type="checkbox" name="iiqe" value="卷三" ${m.iiqe?.includes('卷三')?'checked':''}> 卷三</label><label class="btn small"><input type="checkbox" name="iiqe" value="卷五" ${m.iiqe?.includes('卷五')?'checked':''}> 卷五</label></div></div></div><p class="muted" style="margin-top:14px">首合約日期由系統自動生成；完成入職後生成，不會當月第一天完成入職，首合約日期均為該月 1 日。</p>`; modal(id?'修改新人入職檔案':'加入新人入職檔案',body,fd=>{const d=Object.fromEntries(fd.entries());const iiqe=fd.getAll('iiqe');const uploaded=fd.get('avatar');const next={...m,id:m.id||uid('new'),name:d.name.trim(),englishName:(d.englishName||'').trim(),gender:d.gender||'',code:(d.code||'').trim(),startMonth:d.startDate?d.startDate.slice(0,7):selectedMonth(),startDate:d.startDate||'',codeDate:d.codeDate||'',completionDate:d.completionDate||'',owner:(d.owner||m.owner||'').trim(),status:d.status||'preboarding',role:d.role||'FC',manager:(d.manager||'').trim(),financialPlan:d.financialPlan||'無',education:d.education||'',school:(d.school||'').trim(),currentStep:d.currentStep||stepOptions[0],missingMaterials:(d.missingMaterials||'').trim(),nextAction:(d.nextAction||'').trim(),licenseStatus:d.licenseStatus||'Pending（申請中）',iiqe,avatarName:uploaded&&uploaded.name?uploaded.name:(m.avatarName||''),steps:m.steps||defaultNewSteps()};if(m.id)Object.assign(state.newcomers.find(x=>x.id===m.id),next);else state.newcomers.push(next);save();log('建立新人入職檔案',next.name,next.status==='active'?'已完成':'待跟進');toast(id?'新人檔案已更新':'新人檔案已建立');view.peopleTab='newcomers';render();}); }
  function defaultNewSteps(){ return [{title:'資格、報考及 IIQE',detail:'確認身份、學歷、報考資格及 IIQE 卷別',done:false},{title:'入職申請及文件',detail:'收集身份、學歷、地址及銀行文件',done:false},{title:'牌照／保險局',detail:'提交牌照申請並跟進批核狀態',done:false},{title:'Agent Code',detail:'取得 Agent Code 後補回新人檔案',done:false},{title:'預備首合約',detail:'安排首合約前的團隊、財務及文件準備',done:false},{title:'正式入職及首合約',detail:'完成入職確認與首合約日期生成',done:false},{title:'出 Code 後課程跟進',detail:'依 D0、D5、30／60／90 日節點跟進',done:false}]; }
  function openOnboarding(id){ const n=state.newcomers.find(x=>x.id===id); if(!n)return; modal(`入職流程 · ${n.name}`,`<p class="muted">${monthLabel(n.startMonth)} · 負責人：${esc(n.owner||'未指定')}</p><div class="step-list">${n.steps.map((s,i)=>`<label class="step-item"><input type="checkbox" name="step-${i}" ${s.done?'checked':''}><div><b>${i+1}. ${esc(s.title)}</b><span>${esc(s.detail)}</span></div></label>`).join('')}</div>`,fd=>{n.steps.forEach((s,i)=>s.done=fd.has(`step-${i}`));n.status=n.steps.every(s=>s.done)?'active':n.steps.some(s=>s.done)?'followup':'preboarding';save();log('更新新人入職節點',n.name,n.status==='active'?'已完成':'待跟進');toast('入職流程已更新');render();},'保存節點'); }
  function openAttendance(id){ const a=state.attendance.find(x=>x.id===id)||{month:selectedMonth(),memberId:state.members[0]?.id||'',status:'present',annualRate:0,performance:0,region:'',note:''}; const options=state.members.map(m=>`<option value="${m.id}" ${a.memberId===m.id?'selected':''}>${esc(m.name)} · ${esc(m.code)}</option>`).join(''); modal(id?'修改出勤記錄':'新增出勤記錄',`<div class="form-grid"><div class="field"><label>月份 *</label><input class="input" type="month" name="month" value="${a.month}" required></div><div class="field"><label>人員 *</label><select class="select" name="memberId" required>${options||'<option value="">請先建立成員</option>'}</select></div><div class="field"><label>出勤狀態</label><select class="select" name="status"><option value="present" ${a.status==='present'?'selected':''}>出席</option><option value="partial" ${a.status==='partial'?'selected':''}>部分出席</option><option value="absent" ${a.status==='absent'?'selected':''}>缺席</option><option value="pending" ${a.status==='pending'?'selected':''}>待確認</option></select></div><div class="field"><label>年度累計出勤率 %</label><input class="input" type="number" name="annualRate" min="0" max="100" value="${a.annualRate||0}"></div><div class="field"><label>本月業績 HK$</label><input class="input" type="number" name="performance" min="0" value="${a.performance||0}"></div><div class="field"><label>行政區</label><input class="input" name="region" value="${esc(a.region||'')}"></div></div>`,fd=>{const d=Object.fromEntries(fd.entries());const next={...a,id:a.id||uid('att'),month:d.month,memberId:d.memberId,status:d.status,annualRate:Number(d.annualRate||0),performance:Number(d.performance||0),region:d.region.trim()};if(a.id)Object.assign(state.attendance.find(x=>x.id===a.id),next);else state.attendance.push(next);save();toast('出勤記錄已保存');render();}); }
  function openMeeting(id){ const m=state.meetings.find(x=>x.id===id)||{month:selectedMonth(),title:'業務交流會',date:'',regionDate:'',divisionDate:'',note:'',attendees:[],regionAttendees:[],leaves:[],pending:0}; const memberOptions=state.members.map(x=>`<option value="${x.id}" ${m.attendees?.includes(x.id)?'selected':''}>${esc(x.name)} · ${esc(x.code)}</option>`).join(''); const leaveOptions=state.members.map(x=>`<option value="${x.id}" ${m.leaves?.includes(x.id)?'selected':''}>${esc(x.name)} · ${esc(x.code)}</option>`).join(''); modal(id?'管理業務交流會':'新增業務交流會',`<div class="form-grid"><div class="field"><label>會議月份 *</label><input class="input" type="month" name="month" value="${m.month}" required></div><div class="field"><label>行政總區會議日期</label><input class="input" type="date" name="regionDate" value="${m.regionDate||''}"></div><div class="field"><label>D0174 分區會議日期 *</label><input class="input" type="date" name="divisionDate" value="${m.divisionDate||m.date||''}" required></div><div class="field full"><label>會議主題 *</label><input class="input" name="title" required value="${esc(m.title||'業務交流會')}" placeholder="例如：2026年10月業務交流會"></div><div class="field full"><label>會議備註／通知</label><textarea class="textarea" name="note" rows="3">${esc(m.note||'')}</textarea></div><div class="field full"><label>D0174 分區簽到名單（可多選）</label><select class="select" name="attendees" multiple style="min-height:120px">${memberOptions||'<option disabled>請先建立成員</option>'}</select></div><div class="field full"><label>D0174 請假名單（可多選）</label><select class="select" name="leaves" multiple style="min-height:100px">${leaveOptions||'<option disabled>請先建立成員</option>'}</select></div><div class="field"><label>待核對筆數</label><input class="input" type="number" name="pending" min="0" value="${m.pending||0}"></div></div>`,fd=>{const d=Object.fromEntries(fd.entries());const attendees=[...$('#modal-form [name="attendees"]').selectedOptions].map(o=>o.value);const leaves=[...$('#modal-form [name="leaves"]').selectedOptions].map(o=>o.value);const next={...m,id:m.id||uid('mtg'),month:d.month,date:d.divisionDate,divisionDate:d.divisionDate,regionDate:d.regionDate||'',title:d.title.trim(),note:d.note.trim(),attendees,leaves,pending:Number(d.pending||0),regionAttendees:m.regionAttendees||[]};if(m.id)Object.assign(state.meetings.find(x=>x.id===m.id),next);else state.meetings.push(next);save();toast('業務交流會記錄已保存');render();}); }
  function openLeaver(){ modal('建立離職流程',`<div class="form-grid"><div class="field"><label>姓名 *</label><input class="input" name="name" required></div><div class="field"><label>Agent Code</label><input class="input" name="code"></div><div class="field"><label>離職月份 *</label><input class="input" type="month" name="month" value="${selectedMonth()}" required></div><div class="field"><label>最後工作日 *</label><input class="input" type="date" name="endDate" required></div><div class="field"><label>離職時職級</label><input class="input" name="role"></div><div class="field"><label>上線經理</label><input class="input" name="manager"></div><div class="field full"><label>原因／備註</label><textarea class="textarea" name="reason" rows="3"></textarea></div><div class="field full"><label>負責人</label><input class="input" name="owner"></div></div>`,fd=>{const d=Object.fromEntries(fd.entries());const l={id:uid('leave'),name:d.name.trim(),code:d.code.trim(),month:d.month,endDate:d.endDate,role:d.role.trim(),manager:d.manager.trim(),reason:d.reason.trim(),owner:d.owner.trim(),note:'',steps:defaultLeaveSteps()};state.leavers.push(l);save();log('建立離職處理流程',l.name,'進行中');toast('離職流程已建立');view.selectedLeaver=l.id;render();}); }
  function defaultLeaveSteps(){ return [{title:'填表及歸還公司物品',detail:'表格、身份卡、門卡及公司物品完成歸還',done:false},{title:'保單轉換顧問',detail:'確認保單／承接顧問及辦理說明',done:false},{title:'團隊通知及移群',detail:'完成團隊通知、工作交接與群組移除',done:false},{title:'帳號及權限回收',detail:'郵箱、系統、共用文件與設備權限回收',done:false},{title:'完成確認與歷史記錄',detail:'所有節點確認後，保存結案記錄',done:false}]; }
  function log(title,detail,status){ state.logs.push({id:uid('log'),title,detail,status,kind:status==='待跟進'?'pending':'ok',at:new Date().toISOString()}); state.logs=state.logs.slice(-30); }
  function exportMembers(){ download('d0174-team-directory.csv','\ufeff'+csv([['divisionId','姓名','Agent Code','職級／角色','分組','直接上線','狀態'],...state.members.map(m=>['D0174',m.name,m.code,m.role,m.group,m.manager,m.status])]),'text/csv;charset=utf-8');toast('團隊名單 CSV 已下載'); }
  function exportArchive(){ download('d0174-team-archive.csv','\ufeff'+csv([['divisionId','姓名','Agent Code','角色','狀態','檔案完成'],...state.members.map(m=>['D0174',m.name,m.code,m.role,m.status,m.archiveReady?'是':'否'])]),'text/csv;charset=utf-8');toast('團隊檔案 CSV 已下載'); }
  function exportNewcomers(){ const rows=state.newcomers.filter(n=>n.startMonth===selectedMonth());download(`d0174-newcomers-${selectedMonth()}.csv`,'\ufeff'+csv([['divisionId','姓名','Agent Code','入職月份','入職日期','負責人','完成節點'],...rows.map(n=>['D0174',n.name,n.code,n.startMonth,n.startDate,n.owner,`${n.steps.filter(s=>s.done).length}/${n.steps.length}`])]),'text/csv;charset=utf-8');toast('新人報表 CSV 已下載'); }
  function exportAttendance(){ const rows=state.attendance.filter(a=>a.month===selectedMonth());download(`d0174-attendance-${selectedMonth()}.csv`,'\ufeff'+csv([['divisionId','月份','姓名','Agent Code','出勤狀態','年度出勤率','本月業績'],...rows.map(a=>{const m=state.members.find(x=>x.id===a.memberId)||{};return ['D0174',a.month,m.name||a.name,m.code||a.code,a.status,a.annualRate,a.performance]})]),'text/csv;charset=utf-8');toast('出勤明細 CSV 已下載'); }
  function exportAnalysis(){ const rows=state.attendance.filter(a=>a.month===selectedMonth());download(`d0174-attendance-analysis-${selectedMonth()}.csv`,'\ufeff'+csv([['divisionId','月份','姓名','出勤狀態','年度出勤率','本月業績'],...rows.map(a=>{const m=state.members.find(x=>x.id===a.memberId)||{};return ['D0174',a.month,m.name||a.name,a.status,a.annualRate,a.performance]})]),'text/csv;charset=utf-8');toast('分析底表 CSV 已下載'); }
  function exportMeetings(){ const rows=state.meetings.filter(m=>m.month===selectedMonth());download(`d0174-meetings-${selectedMonth()}.csv`,'\ufeff'+csv([['divisionId','月份','日期','主題','簽到人數','備註'],...rows.map(m=>['D0174',m.month,m.date,m.title,m.attendees?.length||0,m.note])]),'text/csv;charset=utf-8');toast('會議記錄 CSV 已下載'); }
  function exportLeavers(){ const rows=state.leavers.filter(l=>l.month===selectedMonth());download(`d0174-leavers-${selectedMonth()}.csv`,'\ufeff'+csv([['divisionId','姓名','Agent Code','離職月份','最後工作日','原因','完成節點'],...rows.map(l=>['D0174',l.name,l.code,l.month,l.endDate,l.reason,`${l.steps.filter(s=>s.done).length}/${l.steps.length}`])]),'text/csv;charset=utf-8');toast('離職報表 CSV 已下載'); }
  function reportRows(type){ const month=selectedMonth(); if(type==='attendance')return [['月份','姓名','Agent Code','狀態','年度出勤率','業績'],...state.attendance.filter(a=>a.month===month).map(a=>{const m=state.members.find(x=>x.id===a.memberId)||{};return [month,m.name||a.name,m.code||a.code,a.status,a.annualRate,a.performance]})]; if(type==='newcomers')return [['入職月份','姓名','Agent Code','負責人','完成節點'],...state.newcomers.filter(n=>n.startMonth===month).map(n=>[n.startMonth,n.name,n.code,n.owner,`${n.steps.filter(s=>s.done).length}/${n.steps.length}`])]; if(type==='leavers')return [['離職月份','姓名','Agent Code','最後工作日','原因','完成節點'],...state.leavers.filter(l=>l.month===month).map(l=>[l.month,l.name,l.code,l.endDate,l.reason,`${l.steps.filter(s=>s.done).length}/${l.steps.length}`])]; return [['指標','數值'],['D0174 成員',state.members.length],['出勤記錄',state.attendance.filter(a=>a.month===month).length],['新人檔案',state.newcomers.filter(n=>n.startMonth===month).length],['離職流程',state.leavers.filter(l=>l.month===month).length]]; }
  function previewReport(type){ const labels={monthly:'月度團隊運營摘要',attendance:'人員與出勤報表',newcomers:'新人入職報表',leavers:'離職與交接報表'}; const rows=reportRows(type);modal(`預覽 · ${labels[type]}`,`<p class="muted">資料範圍：D0174 · ${monthLabel(selectedMonth())}</p><div class="table-wrap"><table class="table"><thead><tr>${rows[0].map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.slice(1,11).map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${rows[0].length}">尚無資料</td></tr>`}</tbody></table></div>`,()=>{},'關閉'); $('#modal-form .modal-footer .btn.primary').textContent='關閉'; }
  function downloadReport(type){ const names={monthly:'monthly-summary',attendance:'attendance',newcomers:'newcomers',leavers:'leavers'};download(`d0174-${names[type]}-${selectedMonth()}.csv`,'\ufeff'+csv(reportRows(type)),'text/csv;charset=utf-8');toast('報表 CSV 已下載'); }
  function importJson(){ const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=()=>{const file=input.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result);if(!parsed||parsed.divisionId!=='D0174')throw new Error('division');state={...initialState(),...parsed,divisionId:'D0174'};save();toast('D0174 資料已匯入');render();}catch{toast('只接受 divisionId 為 D0174 的 JSON','warn');}};reader.readAsText(file)};input.click();}
  function uploadReport(){ const file=$('#report-file')?.files?.[0]; const func=$('[data-field="upload-function"]')?.value||'monthly'; const month=$('[data-field="upload-month"]')?.value||selectedMonth(); if(!file){toast('請先選擇要上傳的檔案','warn');return;} state.reportUploads=state.reportUploads||[];state.reportUploads.push({id:uid('upload'),divisionId:'D0174',name:file.name,type:file.type||file.name.split('.').pop().toUpperCase(),function:func,month,uploadedAt:new Date().toLocaleString('zh-HK')});save();toast('報表檔案已加入 D0174 上傳記錄');render(); }
  render();
})();
